  ('ef65beb6-531c-4ee0-824f-e723769058a9', 'b4c5d6e7-8f9a-4b79-8c99-0d1e2f3a4b09', '0cf21a65-a773-429c-a930-7bd77babbdf9', 'concept'::public.curated_course_node_type, 'Motor warmups', null, 0),
